                if r < 0 or r >= 4 or c < 0 or c >= 4:
                    ext.append((r,c))
                    ext_set.add((r,c))
                elif not (mask & (1 << (r*4+c))):
                    ext.append((r,c))
                    ext_set.add((r,c))
        if not ext:
            return False
